// pages/dashboard/AdminDashboard.js - VERSION ULTRA SIMPLIFIÉE
import React, { useState } from 'react';
import { useAuthContext } from '../../hooks/useAuthContext';
import { useAdmin } from '../../hooks/UseAdmin';
import { useCourseContext } from '../../context/CourContext';
import './admindashboard.css';

const AdminDashboard = () => {
  const { user } = useAuthContext();
  const { isAdmin } = useAdmin();
  const { courses, addCourse, deleteCourse } = useCourseContext();
  
  const [activeTab, setActiveTab] = useState('overview');
  const [showNewCourseForm, setShowNewCourseForm] = useState(false);
  const [newCourse, setNewCourse] = useState({
    title: '',
    category: 'Développement',
    instructor: '',
    price: '',
    description: '',
    status: 'published'
  });

  // FONCTION SIMPLIFIÉE POUR CRÉER UN COURS
  const handleSubmitCourse = (e) => {
    e.preventDefault();
    
    // IMAGES FIXES POUR CHAQUE CATÉGORIE
    const getCourseImage = (category) => {
      const images = {
        'Développement': 'https://images.unsplash.com/photo-1555066931-4365d14bab8c?w=400&h=250&fit=crop',
        'Design': 'https://images.unsplash.com/photo-1561070791-2526d30994b5?w=400&h=250&fit=crop',
        'Business': 'https://images.unsplash.com/photo-1552664730-d307ca884978?w=400&h=250&fit=crop',
        'Marketing': 'https://images.unsplash.com/photo-1460925895917-afdab827c52f?w=400&h=250&fit=crop'
      };
      return images[category] || 'https://images.unsplash.com/photo-1501504905252-473c47e087f8?w=400&h=250&fit=crop';
    };

    const courseData = {
      title: newCourse.title,
      category: newCourse.category,
      instructor: newCourse.instructor,
      price: parseInt(newCourse.price) || 0,
      originalPrice: Math.round(parseInt(newCourse.price) * 1.3) || 0,
      description: newCourse.description,
      status: newCourse.status,
      level: 'intermediaire',
      featured: false,
      rating: 4.5,
      students: 0,
      duration: "10h 00min",
      image: getCourseImage(newCourse.category) // IMAGE GARANTIE
    };

    addCourse(courseData);
    
    // Réinitialiser
    setNewCourse({
      title: '',
      category: 'Développement',
      instructor: '',
      price: '',
      description: '',
      status: 'published'
    });
    
    setShowNewCourseForm(false);
    alert('✅ Cours créé avec succès !');
  };

  const handleDeleteCourse = (courseId) => {
    if (window.confirm('Êtes-vous sûr de vouloir supprimer ce cours ?')) {
      deleteCourse(courseId);
      alert('✅ Cours supprimé avec succès !');
    }
  };

  if (!isAdmin) {
    return (
      <div className="admin-dashboard">
        <div className="access-denied">
          <h2>Accès Refusé</h2>
          <p>Vous n'avez pas les permissions nécessaires pour accéder à cette page.</p>
        </div>
      </div>
    );
  }

  return (
    <div className="admin-dashboard">
      <div className="admin-layout">
        <nav className="admin-sidebar">
          <div className="sidebar-header">
            <h2>EduPlatform Admin</h2>
            <p>Tableau de Bord</p>
          </div>
          
          <div className="sidebar-nav">
            <button 
              className={`nav-item ${activeTab === 'overview' ? 'active' : ''}`}
              onClick={() => setActiveTab('overview')}
            >
              <span className="nav-icon">📊</span>
              <span className="nav-label">Vue d'ensemble</span>
            </button>
            
            <button 
              className={`nav-item ${activeTab === 'courses' ? 'active' : ''}`}
              onClick={() => setActiveTab('courses')}
            >
              <span className="nav-icon">📚</span>
              <span className="nav-label">Gestion des Cours</span>
            </button>
          </div>
        </nav>

        <main className="admin-main">
          <header className="admin-header">
            <div className="header-title">
              <h1>
                {activeTab === 'overview' && 'Vue d\'Ensemble'}
                {activeTab === 'courses' && 'Gestion des Cours'}
              </h1>
              <p>Bienvenue, {user?.displayName || 'Administrateur'} 👋</p>
            </div>
          </header>

          <div className="admin-content">
            {activeTab === 'overview' && (
              <div className="overview-tab">
                <div className="stats-grid">
                  <div className="stat-card">
                    <div className="stat-value">{courses.length}</div>
                    <div className="stat-label">Total Cours</div>
                  </div>
                </div>
              </div>
            )}

            {activeTab === 'courses' && (
              <div className="courses-tab">
                <div className="tab-header">
                  <h2>Gestion des Cours ({courses.length} cours)</h2>
                  <button 
                    className="btn btn-primary"
                    onClick={() => setShowNewCourseForm(true)}
                  >
                    + Nouveau Cours
                  </button>
                </div>

                {showNewCourseForm && (
                  <div className="modal-overlay">
                    <div className="modal-content">
                      <div className="modal-header">
                        <h3>Créer un Nouveau Cours</h3>
                        <button className="btn-icon" onClick={() => setShowNewCourseForm(false)}>
                          ✕
                        </button>
                      </div>
                      <form onSubmit={handleSubmitCourse}>
                        <div className="form-group">
                          <label>Titre du cours *</label>
                          <input
                            type="text"
                            value={newCourse.title}
                            onChange={(e) => setNewCourse(prev => ({...prev, title: e.target.value}))}
                            required
                            placeholder="Ex: React Avancé"
                          />
                        </div>
                        
                        <div className="form-group">
                          <label>Catégorie *</label>
                          <select
                            value={newCourse.category}
                            onChange={(e) => setNewCourse(prev => ({...prev, category: e.target.value}))}
                            required
                          >
                            <option value="Développement">Développement</option>
                            <option value="Design">Design</option>
                            <option value="Business">Business</option>
                            <option value="Marketing">Marketing</option>
                          </select>
                        </div>
                        
                        <div className="form-group">
                          <label>Formateur *</label>
                          <input
                            type="text"
                            value={newCourse.instructor}
                            onChange={(e) => setNewCourse(prev => ({...prev, instructor: e.target.value}))}
                            required
                            placeholder="Ex: Ahmed Ben Ali"
                          />
                        </div>
                        
                        <div className="form-group">
                          <label>Prix (TND) *</label>
                          <input
                            type="number"
                            value={newCourse.price}
                            onChange={(e) => setNewCourse(prev => ({...prev, price: e.target.value}))}
                            required
                            placeholder="Ex: 89"
                            min="0"
                          />
                        </div>
                        
                        <div className="form-group">
                          <label>Description *</label>
                          <textarea
                            value={newCourse.description}
                            onChange={(e) => setNewCourse(prev => ({...prev, description: e.target.value}))}
                            required
                            placeholder="Description du cours..."
                            rows="3"
                          />
                        </div>

                        <div className="modal-actions">
                          <button type="button" className="btn btn-secondary" onClick={() => setShowNewCourseForm(false)}>
                            Annuler
                          </button>
                          <button type="submit" className="btn btn-primary">
                            Créer le Cours
                          </button>
                        </div>
                      </form>
                    </div>
                  </div>
                )}

                <div className="table-container">
                  <table className="data-table">
                    <thead>
                      <tr>
                        <th>Cours</th>
                        <th>Catégorie</th>
                        <th>Prix</th>
                        <th>Statut</th>
                        <th>Actions</th>
                      </tr>
                    </thead>
                    <tbody>
                      {courses.map(course => (
                        <tr key={course.id}>
                          <td>
                            <div className="course-cell">
                              <div 
                                className="course-thumb-placeholder"
                                style={{
                                  backgroundImage: `url(${course.image})`,
                                  backgroundSize: 'cover',
                                  backgroundPosition: 'center'
                                }}
                              ></div>
                              <div>
                                <strong>{course.title}</strong>
                                <p className="course-description">{course.description}</p>
                              </div>
                            </div>
                          </td>
                          <td>{course.category}</td>
                          <td>
                            <strong>{course.price} TND</strong>
                            {course.originalPrice > course.price && (
                              <div style={{ textDecoration: 'line-through', color: '#999', fontSize: '0.8em' }}>
                                {course.originalPrice} TND
                              </div>
                            )}
                          </td>
                          <td>
                            <span className={`status-badge ${course.status}`}>
                              {course.status === 'published' ? 'Publié' : 'Brouillon'}
                            </span>
                          </td>
                          <td>
                            <button 
                              className="btn-icon btn-danger" 
                              onClick={() => handleDeleteCourse(course.id)}
                            >
                              🗑️
                            </button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )}
          </div>
        </main>
      </div>
    </div>
  );
};

export default AdminDashboard;
